package com.sunmo.stockplatform.analytics.api;
import com.sunmo.stockplatform.analytics.application.ScannerAnalyticsService;import org.springframework.web.bind.annotation.*;import java.time.Instant;
@RestController @RequestMapping("/api/v1")public class ScannerAnalyticsController {private final ScannerAnalyticsService service;public ScannerAnalyticsController(ScannerAnalyticsService service){this.service=service;}@GetMapping("/scanner-detections/{id}/performance")public PerformanceDtos.PerformanceResponse performance(@PathVariable long id){return service.performance(id);}@GetMapping("/scanner-analytics")public PerformanceDtos.AnalyticsResponse analytics(@RequestParam(required=false)Long settingId,@RequestParam Instant from,@RequestParam Instant to){return service.analytics(settingId,from,to);}}
